-- Local/test stand-in for production public.pharmacy_products (same columns). NEVER run against production:
-- the real table already holds 13 347 imported products. Used by tests/global-setup.ts, scripts/e2e-server.mjs
-- and `npm run db:catalog-fixture` (which refuses non-local databases).
CREATE TABLE IF NOT EXISTS public.pharmacy_products (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  article TEXT,
  name TEXT
);

INSERT INTO public.pharmacy_products (article, name)
SELECT * FROM (VALUES
  ('P-500-20', 'Парацетамол 500 мг №20 табл.'),
  ('P-500-10', 'Парацетамол 500 мг №10 табл.'),
  ('P-200', 'ПАРАЦЕТАМОЛ 200 мг №10 табл.'),
  ('DUP-001', 'Бинт стерильный 7 м × 14 см'),
  ('DUP-001', 'Бинт нестерильный 5 м × 10 см'),
  ('E-1', 'Ёлочный экстракт для ванн 200 мл'),
  ('ASP-100', 'Аспирин Кардио 100 мг №28 табл.'),
  ('R_3', 'Перекись водорода раствор 3% 100 мл')
) AS v(article, name)
WHERE NOT EXISTS (SELECT 1 FROM public.pharmacy_products);

INSERT INTO public.pharmacy_products (article, name)
SELECT 'T' || (i % 50), 'Тестовый товар ' || lpad(i::text, 3, '0')
FROM generate_series(1, 120) AS i
WHERE (SELECT count(*) FROM public.pharmacy_products) = 8;
